package com.example.starter.firmware.service;

import com.example.starter.firmware.dto.RatioUpdateRequest;
import com.example.starter.firmware.dto.ReleaseCreateRequest;
import com.example.starter.firmware.dto.ReleaseResponse;
import com.example.starter.firmware.dto.RequestIdOnlyRequest;
import com.example.starter.firmware.error.ApiException;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;

/**
 * 发布单管理：创建、扩量、取消与查询。
 * 同型号至多一张 ACTIVE 发布单，由 active_key 唯一索引在数据库层保证。
 */
@Service
public class ReleaseService {

    private static final RowMapper<ReleaseResponse> MAPPER = (rs, i) -> new ReleaseResponse(
            rs.getLong("id"), rs.getString("model"), rs.getString("from_version"),
            rs.getString("to_version"), rs.getInt("ratio"), rs.getInt("version"),
            rs.getString("status"));

    private final JdbcTemplate jdbc;
    private final IdempotencyService idempotency;

    public ReleaseService(JdbcTemplate jdbc, IdempotencyService idempotency) {
        this.jdbc = jdbc;
        this.idempotency = idempotency;
    }

    /**
     * 创建发布单，版本从 1 开始；目标版本必须与来源版本不同，同型号存在 ACTIVE 发布单时返回 409。
     */
    @Transactional
    public ReleaseResponse create(ReleaseCreateRequest req) {
        String hash = String.join("|", req.model(), req.fromVersion(), req.toVersion(),
                String.valueOf(req.ratio()));
        return idempotency.execute(req.requestId(), "RELEASE_CREATE", hash, ReleaseResponse.class, () -> {
            if (req.fromVersion().equals(req.toVersion())) {
                throw ApiException.badRequest("VERSION_NOT_DISTINCT",
                        "toVersion must differ from fromVersion");
            }
            KeyHolder keyHolder = new GeneratedKeyHolder();
            try {
                jdbc.update(con -> {
                    PreparedStatement ps = con.prepareStatement(
                            "INSERT INTO release_order(model, from_version, to_version, ratio, version, status,"
                                    + " active_key, request_id) VALUES (?,?,?,?,1,'ACTIVE',?,?)",
                            Statement.RETURN_GENERATED_KEYS);
                    ps.setString(1, req.model());
                    ps.setString(2, req.fromVersion());
                    ps.setString(3, req.toVersion());
                    ps.setInt(4, req.ratio());
                    ps.setString(5, req.model());
                    ps.setString(6, req.requestId());
                    return ps;
                }, keyHolder);
            } catch (DuplicateKeyException e) {
                throw ApiException.conflict("ACTIVE_RELEASE_EXISTS",
                        "an ACTIVE release already exists for model: " + req.model());
            }
            long id = keyHolder.getKey().longValue();
            return new ReleaseResponse(id, req.model(), req.fromVersion(), req.toVersion(),
                    req.ratio(), 1, "ACTIVE");
        });
    }

    /**
     * 扩量：比例只增不减，expectedVersion 与当前版本不一致时返回 409，成功后版本加一。
     */
    @Transactional
    public ReleaseResponse updateRatio(long releaseId, RatioUpdateRequest req) {
        String hash = String.join("|", String.valueOf(releaseId), String.valueOf(req.ratio()),
                String.valueOf(req.expectedVersion()));
        return idempotency.execute(req.requestId(), "RELEASE_UPDATE_RATIO", hash, ReleaseResponse.class, () -> {
            ReleaseResponse current = lockById(releaseId);
            if (!"ACTIVE".equals(current.status())) {
                throw ApiException.conflict("RELEASE_NOT_ACTIVE", "release is not ACTIVE: " + releaseId);
            }
            if (current.version() != req.expectedVersion()) {
                throw ApiException.conflict("VERSION_CONFLICT",
                        "expected version " + req.expectedVersion() + " but current is " + current.version());
            }
            if (req.ratio() <= current.ratio()) {
                throw ApiException.conflict("RATIO_NOT_INCREASING",
                        "ratio must be greater than current ratio " + current.ratio());
            }
            jdbc.update("UPDATE release_order SET ratio=?, version=version+1, updated_at=? WHERE id=?",
                    req.ratio(), Timestamp.from(Instant.now()), releaseId);
            return new ReleaseResponse(releaseId, current.model(), current.fromVersion(),
                    current.toVersion(), req.ratio(), current.version() + 1, current.status());
        });
    }

    /**
     * 取消发布单：尚未终结的任务变为 CANCELLED；已终结（SUCCESS/FAILED）任务不受影响。
     * 重复取消按成功处理，返回当前状态。
     */
    @Transactional
    public ReleaseResponse cancel(long releaseId, RequestIdOnlyRequest req) {
        String hash = String.valueOf(releaseId);
        return idempotency.execute(req.requestId(), "RELEASE_CANCEL", hash, ReleaseResponse.class, () -> {
            ReleaseResponse current = lockById(releaseId);
            if ("CANCELLED".equals(current.status())) {
                return current;
            }
            jdbc.update("UPDATE release_order SET status='CANCELLED', active_key=NULL, updated_at=? WHERE id=?",
                    Timestamp.from(Instant.now()), releaseId);
            jdbc.update("UPDATE rollout_task SET status='CANCELLED', updated_at=?"
                            + " WHERE release_id=? AND status='PENDING'",
                    Timestamp.from(Instant.now()), releaseId);
            return new ReleaseResponse(current.id(), current.model(), current.fromVersion(),
                    current.toVersion(), current.ratio(), current.version(), "CANCELLED");
        });
    }

    /**
     * 查询发布单；不存在时返回 404。
     */
    @Transactional(readOnly = true)
    public ReleaseResponse get(long releaseId) {
        List<ReleaseResponse> rows = jdbc.query(
                "SELECT * FROM release_order WHERE id=?", MAPPER, releaseId);
        if (rows.isEmpty()) {
            throw ApiException.notFound("RELEASE_NOT_FOUND", "release not found: " + releaseId);
        }
        return rows.get(0);
    }

    /**
     * 按主键锁定发布单行（FOR UPDATE），用于写操作间串行化；不存在时返回 404。
     */
    private ReleaseResponse lockById(long releaseId) {
        List<ReleaseResponse> rows = jdbc.query(
                "SELECT * FROM release_order WHERE id=? FOR UPDATE", MAPPER, releaseId);
        if (rows.isEmpty()) {
            throw ApiException.notFound("RELEASE_NOT_FOUND", "release not found: " + releaseId);
        }
        return rows.get(0);
    }
}

package com.example.starter.firmware.service;

import com.example.starter.firmware.dto.PullRequest;
import com.example.starter.firmware.dto.ReceiptRequest;
import com.example.starter.firmware.dto.TaskResponse;
import com.example.starter.firmware.error.ApiException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * 投放任务：设备拉取、回执收敛与明细查询。
 * 拉取与取消通过对发布单行加锁串行化；回执与取消通过对任务行加锁/行级更新串行化，
 * 两种并发都形成一致的提交顺序，已成功设备不回滚。
 */
@Service
public class TaskService {

    private static final RowMapper<TaskResponse> MAPPER = (rs, i) -> new TaskResponse(
            rs.getLong("id"), rs.getLong("release_id"), rs.getString("device_id"),
            rs.getString("model"), rs.getString("from_version"), rs.getString("to_version"),
            rs.getString("status"));

    private final JdbcTemplate jdbc;
    private final IdempotencyService idempotency;

    public TaskService(JdbcTemplate jdbc, IdempotencyService idempotency) {
        this.jdbc = jdbc;
        this.idempotency = idempotency;
    }

    /**
     * 设备拉取任务：先返回该设备在该型号 ACTIVE 发布单下的已有任务（含 FAILED，本轮不重新投放）；
     * 否则仅当型号与当前版本匹配、分桶号小于投放比例时创建任务。无匹配发布单或不满足条件时返回 404。
     */
    @Transactional
    public TaskResponse pull(PullRequest req) {
        return idempotency.execute(req.requestId(), "TASK_PULL", req.deviceId(), TaskResponse.class, () -> {
            Map<String, Object> device = jdbc.query(
                    "SELECT device_id, model, current_version, bucket FROM device WHERE device_id=?",
                    rs -> rs.next() ? Map.of(
                            "device_id", rs.getString("device_id"),
                            "model", rs.getString("model"),
                            "current_version", rs.getString("current_version"),
                            "bucket", rs.getInt("bucket")) : null,
                    req.deviceId());
            if (device == null) {
                throw ApiException.notFound("DEVICE_NOT_FOUND", "device not found: " + req.deviceId());
            }
            // 锁定该型号 ACTIVE 发布单，与取消操作串行化。
            List<Map<String, Object>> releases = jdbc.queryForList(
                    "SELECT id, from_version, to_version, ratio FROM release_order"
                            + " WHERE model=? AND status='ACTIVE' FOR UPDATE",
                    device.get("model"));
            if (releases.isEmpty()) {
                throw ApiException.notFound("NO_TASK_AVAILABLE", "no ACTIVE release for device model");
            }
            Map<String, Object> release = releases.get(0);
            long releaseId = ((Number) release.get("id")).longValue();

            List<TaskResponse> existing = jdbc.query(
                    "SELECT * FROM rollout_task WHERE release_id=? AND device_id=?",
                    MAPPER, releaseId, req.deviceId());
            if (!existing.isEmpty()) {
                return existing.get(0);
            }

            int ratio = ((Number) release.get("ratio")).intValue();
            String fromVersion = (String) release.get("from_version");
            boolean eligible = fromVersion.equals(device.get("current_version"))
                    && ((Number) device.get("bucket")).intValue() < ratio;
            if (!eligible) {
                throw ApiException.notFound("NO_TASK_AVAILABLE",
                        "device is not eligible for the ACTIVE release");
            }

            KeyHolder keyHolder = new GeneratedKeyHolder();
            jdbc.update(con -> {
                PreparedStatement ps = con.prepareStatement(
                        "INSERT INTO rollout_task(release_id, device_id, model, from_version, to_version, status)"
                                + " VALUES (?,?,?,?,?,'PENDING')",
                        Statement.RETURN_GENERATED_KEYS);
                ps.setLong(1, releaseId);
                ps.setString(2, req.deviceId());
                ps.setString(3, (String) device.get("model"));
                ps.setString(4, fromVersion);
                ps.setString(5, (String) release.get("to_version"));
                return ps;
            }, keyHolder);
            long taskId = keyHolder.getKey().longValue();
            return new TaskResponse(taskId, releaseId, req.deviceId(), (String) device.get("model"),
                    fromVersion, (String) release.get("to_version"), "PENDING");
        });
    }

    /**
     * 设备回执：首次回执终结任务，仅 SUCCESS 更新设备当前版本；同结果重复回执成功，
     * 不同结果返回 409；已取消任务的迟到回执返回 409 且不更新设备版本。
     */
    @Transactional
    public TaskResponse receipt(long taskId, ReceiptRequest req) {
        String hash = String.join("|", String.valueOf(taskId), req.result());
        return idempotency.execute(req.requestId(), "TASK_RECEIPT", hash, TaskResponse.class, () -> {
            List<TaskResponse> rows = jdbc.query(
                    "SELECT * FROM rollout_task WHERE id=? FOR UPDATE", MAPPER, taskId);
            if (rows.isEmpty()) {
                throw ApiException.notFound("TASK_NOT_FOUND", "task not found: " + taskId);
            }
            TaskResponse task = rows.get(0);
            switch (task.status()) {
                case "PENDING" -> {
                    jdbc.update("UPDATE rollout_task SET status=?, updated_at=? WHERE id=?",
                            req.result(), Timestamp.from(Instant.now()), taskId);
                    if ("SUCCESS".equals(req.result())) {
                        jdbc.update("UPDATE device SET current_version=? WHERE device_id=?",
                                task.toVersion(), task.deviceId());
                    }
                    return new TaskResponse(task.id(), task.releaseId(), task.deviceId(), task.model(),
                            task.fromVersion(), task.toVersion(), req.result());
                }
                case "SUCCESS", "FAILED" -> {
                    if (task.status().equals(req.result())) {
                        return task;
                    }
                    throw ApiException.conflict("RECEIPT_CONFLICT",
                            "task already finalized as " + task.status());
                }
                default -> throw ApiException.conflict("TASK_CANCELLED",
                        "task was cancelled, receipt rejected");
            }
        });
    }

    /**
     * 任务明细查询，支持按发布单与设备过滤。
     */
    @Transactional(readOnly = true)
    public List<TaskResponse> query(Long releaseId, String deviceId) {
        StringBuilder sql = new StringBuilder("SELECT * FROM rollout_task WHERE 1=1");
        List<Object> args = new ArrayList<>();
        if (releaseId != null) {
            sql.append(" AND release_id=?");
            args.add(releaseId);
        }
        if (deviceId != null) {
            sql.append(" AND device_id=?");
            args.add(deviceId);
        }
        sql.append(" ORDER BY id");
        return jdbc.query(sql.toString(), MAPPER, args.toArray());
    }
}

